class Parent {
    static String who() { return "Parent"; }
    String name = "Parent";
    String describe() { return "tôi là " + name; }
}

class Child extends Parent {
    static String who() { return "Child"; }   // hiding, không phải override
    String name = "Child";                    // field hiding
    @Override String describe() { return "tôi là " + name; }
}

Parent p = new Child();
System.out.println(p.who());        // Parent  <- theo kiểu khai báo
System.out.println(p.name);         // Parent  <- theo kiểu khai báo
System.out.println(p.describe());   // tôi là Child <- dynamic dispatch
System.out.println(((Child) p).name); // Child
// object thật chứa CẢ HAI field name

class Parent {
    static { System.out.print("1"); }
    { System.out.print("2"); }
    Parent() { System.out.print("3"); init(); }
    void init() { }
}

class Child extends Parent {
    static { System.out.print("4"); }
    { System.out.print("5"); }
    private String value = "hello";
    Child() { System.out.print("6"); }

    @Override
    void init() {
        System.out.print("[value=" + value + "]"); // null!
    }
}

new Child();
